from pypdf import PdfReader

reader = PdfReader("/root/sc100-blank.pdf")

# Focus on checkbox fields to understand their structure
fields = reader.get_fields()
for name, field in sorted(fields.items()):
    field_type = field.get('/FT', '')
    if field_type == '/Btn' and 'Print' not in name and 'Reset' not in name and 'Save' not in name:
        print(f"Field: {name}")
        print(f"  Alt Name: {field.get('/TU', '')}")
        print(f"  Value: {field.get('/V', '')}")
        # Check for appearance states
        if '/AP' in field:
            ap = field['/AP']
            if '/N' in ap:
                print(f"  Normal AP keys: {list(ap['/N'].keys())}")
        if '/AS' in field:
            print(f"  AS: {field['/AS']}")
        # Check kids
        if '/Kids' in field:
            print(f"  Has Kids: Yes")
            for kid in field['/Kids']:
                kid_obj = kid.get_object()
                if '/AP' in kid_obj:
                    ap = kid_obj['/AP']
                    if '/N' in ap:
                        print(f"    Kid Normal AP keys: {list(ap['/N'].keys())}")
                if '/AS' in kid_obj:
                    print(f"    Kid AS: {kid_obj['/AS']}")
        print()
EOF
